+/* HeroSection.module.css */
+span {
+  color: #fff;
+}
+.heroSection { 
+  margin-bottom: 96px;
+}
+
+.slider_container {
+  max-width: 640px;
+}
+.slogan_block {
+display: flex;
+    flex-direction: column;
+    align-items: flex-start;
+    margin: 72px 0 0 120px;
+    width: 531px;
+    flex-shrink: 0;
+    box-sizing: border-box;
+    align-self: flex-start;
+}
+
+.construction_repair_gomel {
+    font-family: 'Roboto', sans-serif;
+  font-size: 60px;
+  line-height: 70px;
+  font-weight: bold;
+  color: #ffffff;
+  margin: 0;
+}
+.button {
+   width: 300px;
+  height: 51px;
+  
+  background-color: #1c1d1e; 
+  border: 3px solid #ff7a00; 
+  border-radius: 10px;       
+  
+  display: flex;
+  justify-content: center;
+  align-items: center;
+  
+  font-family: 'Montserrat', sans-serif;
+  font-size: 16px; 
+  font-weight: 500; 
+  color: #ffffff;
+  cursor: pointer;
+  transition: background-color 0.3s ease, color 0.3s ease;
+  box-sizing: border-box;
+}
+
+.button:hover {
+  background-color: #ff7a00;
+  color: #1c1d1e ; 
+}
+
+.future_together {
+  display: block; 
+  
+  font-family: 'Montserrat', sans-serif;
+  font-size: 22px;
